int ladderLength(char *beginWord, char *endWord, char **wordList, int wordListSize) {
  int hasEnd = 0;
  for (int i = 0; i < wordListSize; i++) {
    if (strcmp(wordList[i], endWord) == 0) hasEnd = 1;
  }
  if (!hasEnd) return 0;

  bool *used = (bool *)calloc(wordListSize, sizeof(bool));
  char(*queue)[16] = malloc(sizeof(char) * 16 * (wordListSize + 1));
  int head = 0, tail = 0;
  strcpy(queue[tail++], beginWord);

  int level = 1;
  int result = 0;

  while (head < tail) {
    int levelSize = tail - head;
    for (int i = 0; i < levelSize; i++) {
      char *word = queue[head++];
      if (strcmp(word, endWord) == 0) {
        result = level;
        break;
      }
      int len = (int)strlen(word);
      for (int j = 0; j < len; j++) {
        char origin = word[j];
        for (char c = 'a'; c <= 'z'; c++) {
          if (c == origin) continue;
          word[j] = c;
          for (int k = 0; k < wordListSize; k++) {
            if (!used[k] && strcmp(wordList[k], word) == 0) {
              used[k] = true;
              strcpy(queue[tail++], wordList[k]);
              break;
            }
          }
        }
        word[j] = origin;
      }
    }
    if (result) break;
    level++;
  }

  free(used);
  free(queue);
  return result;
}

class Solution {
public:
  int ladderLength(string beginWord, string endWord, vector<string> &wordList) {
    unordered_set<string> dict(wordList.begin(), wordList.end());
    if (!dict.count(endWord)) return 0;

    queue<string> q;
    q.push(beginWord);
    int level = 1;

    while (!q.empty()) {
      int size = q.size();
      for (int i = 0; i < size; i++) {
        string word = q.front();
        q.pop();
        if (word == endWord) return level;
        for (size_t j = 0; j < word.size(); j++) {
          char origin = word[j];
          for (char c = 'a'; c <= 'z'; c++) {
            if (c == origin) continue;
            word[j] = c;
            if (dict.count(word)) {
              q.push(word);
              dict.erase(word);
            }
          }
          word[j] = origin;
        }
      }
      level++;
    }

    return 0;
  }
};

