use std::collections::{HashSet, VecDeque};

impl Solution {
  pub fn ladder_length(begin_word: String, end_word: String, word_list: Vec<String>) -> i32 {
    let mut dict: HashSet<String> = word_list.into_iter().collect();
    if !dict.contains(&end_word) {
      return 0;
    }

    let mut queue: VecDeque<String> = VecDeque::new();
    queue.push_back(begin_word);
    let mut level = 1;

    while !queue.is_empty() {
      let size = queue.len();
      for _ in 0..size {
        let word = queue.pop_front().unwrap();
        if word == end_word {
          return level;
        }
        let bytes = word.into_bytes();
        for j in 0..bytes.len() {
          for c in b'a'..=b'z' {
            if c == bytes[j] {
              continue;
            }
            let mut nb = bytes.clone();
            nb[j] = c;
            let cand = String::from_utf8(nb).unwrap();
            if dict.remove(&cand) {
              queue.push_back(cand);
            }
          }
        }
      }
      level += 1;
    }

    0
  }
}

const ladderLength = (beginWord: string, endWord: string, wordList: string[]): number => {
  const dict = new Set<string>(wordList);
  if (!dict.has(endWord)) return 0;

  let queue: string[] = [beginWord];
  let level = 1;
  const base = 'a'.charCodeAt(0);

  while (queue.length > 0) {
    const size = queue.length;
    const next: string[] = [];
    for (let i = 0; i < size; i++) {
      const word = queue[i];
      if (word === endWord) return level;
      for (let j = 0; j < word.length; j++) {
        for (let k = 0; k < 26; k++) {
          const c = String.fromCharCode(base + k);
          if (c === word[j]) continue;
          const cand = word.slice(0, j) + c + word.slice(j + 1);
          if (dict.has(cand)) {
            dict.delete(cand);
            next.push(cand);
          }
        }
      }
    }
    queue = next;
    level++;
  }

  return 0;
};
